DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-15865'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='8Z6770' OR source_url ~ '[?&]id=15865(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='87b95db6-2d30-4f63-86ec-4d49a2c56770' OR slug='sam-direct-sale-shophouse-su-charoen-patong-8z6770' OR description ILIKE '%8Z6770%' OR (abs(latitude-7.88469)<0.0001 AND abs(longitude-98.29789)<0.0001 AND abs(land_area_sqm-73.2)<1)) THEN RAISE NOTICE 'SAM 8Z6770 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;

รายการรับโอนกรรมสิทธิ์ระบุเป็นอาคารพาณิชย์ 4 ชั้น เลขที่ 162/143 ที่ดินรูปสี่เหลี่ยมผืนผ้า ขนาดแปลงในรายละเอียดและผัง SAM ระบุด้านทิศเหนือติดถนนกว้างประมาณ 4 เมตร ลึกประมาณ 18 เมตร แต่ช่องสรุปหน้าเว็บระบุหน้ากว้าง 6 เมตร ลึก 9 เมตร ข้อมูลสองส่วนไม่ตรงกัน ต้องตรวจโฉนด ผังและขนาดจริงก่อนซื้อ โดยพื้นที่ดินใช้ 18.3 ตร.ว. ตามต้นทาง

สิทธิทางเข้าและค่าส่วนกลาง: SAM ระบุว่าทางเข้าเป็นแปลงคงเหลือโฉนด 11996 ซึ่งเดิมอยู่ภายใต้การจัดสรร ก่อนแบ่งเป็นแปลงทรัพย์โฉนด 12588 และยังใช้สิทธิเข้าออกของแปลงก่อนแบ่งแยกได้ตามข้อมูลต้นทาง หากมีการจัดตั้งนิติบุคคล ทรัพย์ต้องจ่ายค่าส่วนกลางเสมือนที่ดินภายใต้การจัดสรร ผู้ซื้อควรตรวจหลักฐานสิทธิใช้ทาง สถานะนิติบุคคล ค่าส่วนกลางและยอดค้างจริงก่อนเสนอซื้อ ต้นทางไม่ระบุอัตราหรือยอดเงิน ผิวถนนคอนกรีตกว้างประมาณ 6 เมตร เขตทางประมาณ 9 เมตร

ต้นทางระบุเขตผังเมืองสีส้ม อยู่ในย่านที่อยู่อาศัย พาณิชยกรรมและแหล่งท่องเที่ยว ใกล้ห้างจังซีลอน หาดป่าตอง ตลาดสดบ้านข้าม และโรงพยาบาลป่าตอง ข้อมูลทำเลไม่ใช่การยืนยันใบอนุญาตโรงแรมหรือกิจการให้เช่ารายวัน และไม่ได้ประมาณรายได้หรือผลตอบแทน

การเดินทางตาม SAM: ใช้ถนนผังเมืองสาย ก. จากโรงพยาบาลป่าตองมุ่งหน้าแหลมพรหมเทพ ผ่านตลาดสดบ้านข้ามและห้างจังซีลอน เลี้ยวซ้ายเข้าโครงการสุเจริญป่าตองประมาณ 120 เมตร แล้วเลี้ยวขวาอีกประมาณ 20 เมตร ทรัพย์อยู่ด้านซ้ายมือ ต้นทางอ้างร้าน 7-Eleven และ FamilyMart เป็นจุดสังเกตปากซอย ควรใช้พิกัดประกอบเพราะร้านค้าอาจเปลี่ยนแปลง

ภาพอาคารและภายในแสดงวันที่ 10 ธันวาคม 2567 รวม 19 ภาพ มีภาพห้อง ทางเดิน ครัว ห้องน้ำ ระเบียง ทางเข้า ผังแปลงและแผนที่ ควรตรวจสภาพพื้น ผนัง ฝ้าเพดาน การรั่วซึม ระบบไฟฟ้าและประปาปัจจุบัน

หน้า SAM แสดงสถานะซื้อตรงและราคาข้างต้น ณ วันที่ 11 กันยายน 2569 ติดต่อ SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส 8Z6770 เพื่อยืนยันสถานะพร้อมขาย ราคา การนัดชม ขนาดแปลง สิทธิใช้ทาง ค่าส่วนกลางและเงื่อนไขล่าสุด

