INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=15865&keyref=6007684', '8Z6770', now(), 'Official source captured 2026-09-11. THB 6,886,000; Chanote 12588, 18.3 sq.wah; four storeys; five bedrooms/seven bathrooms. Source dimensions conflict: summary 6x9 m vs detail/plan approx 4x18 m. Retained access via parent 11996 and common fees conditional on juristic entity establishment disclosed; current fees/status not inferred. Nineteen source images dated 2024-12-10. Navigation/map agree. Nearby 8Z7193 and 8Z6607 are different properties by code/address/title/area; no exact duplicate.') ;
